func testManifestoEletronicoToManyAddOpMdfeManifestoEletronicoCiots(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a ManifestoEletronico
	var b, c, d, e ManifestoEletronicoCiot

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, manifestoEletronicoDBTypes, false, strmangle.SetComplement(manifestoEletronicoPrimaryKeyColumns, manifestoEletronicoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ManifestoEletronicoCiot{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, manifestoEletronicoCiotDBTypes, false, strmangle.SetComplement(manifestoEletronicoCiotPrimaryKeyColumns, manifestoEletronicoCiotColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ManifestoEletronicoCiot{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddMdfeManifestoEletronicoCiots(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.MdfeID != first.MdfeID {
			t.Error("foreign key was wrong value", a.MdfeID, first.MdfeID)
		}
		if a.MdfeID != second.MdfeID {
			t.Error("foreign key was wrong value", a.MdfeID, second.MdfeID)
		}

		if first.R.Mdfe != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Mdfe != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.MdfeManifestoEletronicoCiots[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.MdfeManifestoEletronicoCiots[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.MdfeManifestoEletronicoCiots().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
