func testManifestoEletronicoToOneEmpresaFilialUsingEmf(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local ManifestoEletronico
	var foreign EmpresaFilial

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, manifestoEletronicoDBTypes, false, manifestoEletronicoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ManifestoEletronico struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, empresaFilialDBTypes, false, empresaFilialColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize EmpresaFilial struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.EmfID = foreign.EmfID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Emf().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.EmfID != foreign.EmfID {
		t.Errorf("want: %v, got %v", foreign.EmfID, check.EmfID)
	}

	ranAfterSelectHook := false
	AddEmpresaFilialHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *EmpresaFilial) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := ManifestoEletronicoSlice{&local}
	if err = local.L.LoadEmf(ctx, tx, false, (*[]*ManifestoEletronico)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Emf = nil
	if err = local.L.LoadEmf(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Emf == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

